import ast

import pytest

from ansible.errors import AnsibleError
from ansible.executor import module_common as mc


PREFIX = ('ansible_collections', 'ns', 'coll', 'plugins', 'module_utils')


def test_redirect_expands_fqcn_and_emits_deprecation(mocker):
    mocker.patch.object(mc, '_get_collection_metadata', return_value={
        'plugin_routing': {'module_utils': {'old': {
            'redirect': 'other.coll.new',
            'deprecation': {'warning': 'use new', 'removal_version': '2.0', 'removal_date': '2027-01-01'},
        }}}
    })
    warning = mocker.patch.object(mc.display, 'deprecated')
    locator = mc.CollectionModuleUtilLocator(PREFIX + ('old',))
    assert locator.redirect_target == ('ansible_collections', 'other', 'coll', 'plugins', 'module_utils', 'new')
    assert b'old' not in locator.source.encode() if isinstance(locator.source, str) else True
    warning.assert_called_once_with('use new', version='2.0', date='2027-01-01', collection_name='ns.coll')


def test_tombstone_includes_collection(mocker):
    mocker.patch.object(mc, '_get_collection_metadata', return_value={
        'plugin_routing': {'module_utils': {'old': {'tombstone': {
            'warning': 'removed', 'removal_version': '3.0', 'removal_date': '2028-01-01'}}}}
    })
    with pytest.raises(AnsibleError, match='removed.*3.0.*2028-01-01'):
        mc.CollectionModuleUtilLocator(PREFIX + ('old',))


def test_package_initializer_relative_imports():
    finder = mc.ModuleDepFinder('.'.join(PREFIX + ('pkg',)), is_package=True)
    finder.visit(ast.parse('from .submod import Value\\nfrom ..cousin.submod import Other'))
    assert PREFIX + ('pkg', 'submod', 'Value') in finder.submodules
    assert PREFIX + ('cousin', 'submod', 'Other') in finder.submodules


def test_ambiguous_candidates_only_below_module_utils():
    assert mc.CollectionModuleUtilLocator(PREFIX + ('thing',), True).candidate_names_joined() == [
        '.'.join(PREFIX + ('thing',))]
